// Normaliza la aplicación del VSL y arma la nota para GHL.
const b = $input.first().json.body || {};

const REVENUE_LABEL = {
  '5-10k': '$5,000 - $10,000 / mes',
  '10-20k': '$10,000 - $20,000 / mes',
  '20-40k': '$20,000 - $40,000 / mes',
  '50k+': '$50,000+ / mes'
};

const parts = String(b.full_name || '').trim().split(/\s+/);
const firstName = parts.shift() || '';
const lastName = parts.join(' ');

const qualified = b.qualified === true || b.qualified === 'true';

const note = [
  `APLICACION VSL — ${qualified ? 'CALIFICA' : 'NO CALIFICA'}`,
  '',
  `1. Dueno de compania de pintura en EE.UU.: ${b.owner_us_painting_company === 'si' ? 'Si' : 'No'}`,
  `2. Facturacion mensual: ${REVENUE_LABEL[b.monthly_revenue] || b.monthly_revenue || '-'}`,
  `3. Licencia y seguro en regla: ${b.licensed_insured === 'si' ? 'Si' : 'No'}`,
  `4. Area de servicio: ${b.service_area || '-'}`,
  '',
  `Compania: ${b.company || '-'}`,
  qualified ? null : `Motivo de descalificacion: ${b.disqualified_reason || '-'}`,
  `Enviado: ${b.submitted_at || new Date().toISOString()}`,
  `Pagina: ${b.page || '-'}`
].filter(x => x !== null).join('\n');

return [{
  json: {
    firstName,
    lastName,
    email: String(b.email || '').trim().toLowerCase(),
    phone: String(b.phone || '').trim(),
    companyName: b.company || '',
    qualified,
    tags: ['top-coat-media', 'vsl', qualified ? 'vsl-calificado' : 'vsl-no-calificado'],
    note
  }
}];
